import React,{useEffect,useMemo,useState} from 'react'
import {createRoot} from 'react-dom/client'
import {Search,Menu,Sun,Moon,ChevronRight,ArrowLeft,MapPin,Shield,Zap,Swords,CalendarDays,Calculator,Heart,Info} from 'lucide-react'
import {pokemon,moves,items,abilities,locations,trainers,types,nav,evolutionChains,events,loadDexData,loadEntityDetail,loadToolData,DetailKind,Localized,Pokemon,Move,Item,EvolutionStep,Location as DexLocation,APP_BASE,assetUrl} from './data'
import './styles.css'
